//! Golden tests: charts and flows through `ChartService` + `IztroAdapter` equal JS iztro
//! 2.6.3 (fixture generated by `tools/fixtures/iztro/generate.mjs`). Zero mismatches.

use chart_svc::adapters::engine::{engine_lunar_date, IztroAdapter};
use chart_svc::application::birth::{normalize, NormalizedBirth};
use chart_svc::application::service::{ChartRequest, ChartService};
use chart_svc::domain::calendar::{
    day_can_chi, solar_to_lunar, Branch, CalendarKind, LunarDate, Stem,
};
use chart_svc::domain::chart::{Brightness, Chart, Flow, FlowLayer, Gender, Mutagen, StarKey};
use serde_json::Value;
use std::sync::OnceLock;
use time::macros::format_description;
use time::{Date, PrimitiveDateTime};

const FIXTURE: &str = include_str!("fixtures/iztro-golden.json");

fn fixture() -> &'static Value {
    static F: OnceLock<Value> = OnceLock::new();
    F.get_or_init(|| serde_json::from_str(FIXTURE).expect("fixture parses"))
}

fn cases(kind: &str) -> Vec<&'static Value> {
    fixture()["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .filter(|c| c["kind"] == kind)
        .collect()
}

fn service() -> ChartService<IztroAdapter> {
    ChartService::new(IztroAdapter)
}

