// ---- both sides rendered to comparable text lines ----------------------------------------

fn s(v: &Value) -> &str {
    v.as_str().expect("string")
}

fn opt_key<T>(v: Option<T>, key: fn(T) -> &'static str) -> &'static str {
    v.map_or("-", key)
}

/// The fields compared for a chart: cục, mệnh chủ, thân chủ, thân palace, year can chi,
/// then per palace (from Dần) its key, branch, stem, decade, major and minor stars with
/// brightness and mutagen.
fn chart_lines(c: &Chart) -> Vec<String> {
    let mut out = vec![
        format!("cuc {} {}", c.cuc.name_vi(), c.cuc.number),
        format!("menhChu {}", c.menh_chu.key()),
        format!("thanChu {}", c.than_chu.key()),
        format!("thanPalace {}", c.than_palace.key()),
        format!("year {} {}", c.year.stem.key(), c.year.branch.key()),
    ];
    for p in &c.palaces {
        let stars = |list: &[chart_svc::domain::chart::StarInPalace]| {
            list.iter()
                .map(|st| {
                    format!(
                        "{}/{}/{}",
                        st.key.key(),
                        opt_key(st.brightness, Brightness::key),
                        opt_key(st.mutagen, Mutagen::key)
                    )
                })
                .collect::<Vec<_>>()
                .join(",")
        };
        out.push(format!(
            "palace {} {} {} {}-{} major[{}] minor[{}]",
            p.branch.key(),
            p.key.key(),
            p.stem.key(),
            p.decade.0,
            p.decade.1,
            stars(&p.major),
            stars(&p.minor)
        ));
    }
    out
}

fn expected_chart_lines(e: &Value) -> Vec<String> {
    let number = match s(&e["five"]).chars().next() {
        Some('水') => 2,
        Some('木') => 3,
        Some('金') => 4,
        Some('土') => 5,
        _ => 6,
    };
    let body_palace = e["palaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|p| p["body"] == true)
        .expect("body palace");
    let mut out = vec![
        format!("cuc {} {number}", cuc_label(s(&e["five"]))),
        format!("menhChu {}", star_key(s(&e["soul"]))),
        format!("thanChu {}", star_key(s(&e["body"]))),
        format!("thanPalace {}", palace_key(s(&body_palace["name"]))),
        format!(
            "year {} {}",
            stem_key(s(&e["year"][0])),
            branch_key(s(&e["year"][1]))
        ),
    ];
    for p in e["palaces"].as_array().unwrap() {
        let stars = |list: &Value| {
            list.as_array()
                .unwrap()
                .iter()
                .map(|st| {
                    format!(
                        "{}/{}/{}",
                        star_key(s(&st[0])),
                        brightness_key(s(&st[1])),
                        mutagen_key(s(&st[2]))
                    )
                })
                .collect::<Vec<_>>()
                .join(",")
        };
        out.push(format!(
            "palace {} {} {} {}-{} major[{}] minor[{}]",
            branch_key(s(&p["branch"])),
            palace_key(s(&p["name"])),
            stem_key(s(&p["stem"])),
            p["decade"][0],
            p["decade"][1],
            stars(&p["major"]),
            stars(&p["minor"])
        ));
    }
    assert_eq!(
        e["bodyBranch"], body_palace["branch"],
        "fixture body palace is inconsistent"
    );
    out
}

fn layer_line(name: &str, l: &FlowLayer) -> String {
    let m: Vec<_> = l
        .mutagens
        .iter()
        .map(|(st, mu)| format!("{}/{}", st.key(), mu.key()))
        .collect();
    format!(
        "{name} palace {} stem {} [{}]",
        l.palace_branch.key(),
        l.stem.key(),
        m.join(",")
    )
}

fn expected_layer_line(name: &str, e: &Value) -> String {
    let index = usize::try_from(e["index"].as_u64().unwrap()).unwrap();
    let m: Vec<_> = e["mutagens"]
        .as_array()
        .unwrap()
        .iter()
        .zip(Mutagen::ORDER)
        .map(|(st, mu)| format!("{}/{}", star_key(s(st)), mu.key()))
        .collect();
    format!(
        "{name} palace {} stem {} [{}]",
        Branch::ALL[(index + 2) % 12].key(),
        stem_key(s(&e["stem"])),
        m.join(",")
    )
}

fn flow_lines(f: &Flow) -> Vec<String> {
    vec![
        layer_line("yearly", &f.yearly),
        layer_line("monthly", &f.monthly),
        layer_line("daily", &f.daily),
        format!("day {} {}", f.day.stem.key(), f.day.branch.key()),
    ]
}

fn expected_flow_lines(e: &Value) -> Vec<String> {
    vec![
        expected_layer_line("yearly", &e["yearly"]),
        expected_layer_line("monthly", &e["monthly"]),
        expected_layer_line("daily", &e["daily"]),
        // The daily layer's stem and branch are the day's can chi.
        format!(
            "day {} {}",
            stem_key(s(&e["daily"]["stem"])),
            branch_key(s(&e["daily"]["branch"]))
        ),
    ]
}

// ---- inputs ------------------------------------------------------------------------------

fn date(v: &Value) -> Date {
    Date::parse(s(v), format_description!("[year]-[month]-[day]")).expect("date")
}

fn lunar(v: &Value) -> LunarDate {
    let n = |i: usize| v[i].as_i64().unwrap();
    LunarDate {
        year: i32::try_from(n(0)).unwrap(),
        month: u8::try_from(n(1)).unwrap(),
        day: u8::try_from(n(2)).unwrap(),
        leap: v[3].as_bool().unwrap(),
    }
}

fn gender(v: &Value) -> Gender {
    match s(v) {
        "male" => Gender::Male,
        "female" => Gender::Female,
        other => panic!("gender {other}"),
    }
}

fn hour(v: &Value) -> Branch {
    Branch::ALL[usize::try_from(v.as_u64().unwrap()).unwrap()]
}

fn request(c: &Value, cal: CalendarKind) -> ChartRequest {
    ChartRequest {
        birth: NormalizedBirth::from_parts(date(&c["solar"]), hour(&c["timeIndex"]), cal),
        gender: gender(&c["gender"]),
    }
}

/// Compares and records differences as `id: field: got != want`.
fn diff(id: &str, got: &[String], want: &[String], out: &mut Vec<String>) {
    if got.len() != want.len() {
        out.push(format!("{id}: {} lines != {}", got.len(), want.len()));
    }
    for (g, w) in got.iter().zip(want) {
        if g != w {
            out.push(format!("{id}:\n   got  {g}\n   want {w}"));
        }
    }
}

fn assert_no_mismatches(what: &str, n: usize, mismatches: &[String]) {
    assert!(
        mismatches.is_empty(),
        "{what}: {} mismatches in {n} cases:\n{}",
        mismatches.len(),
        mismatches
            .iter()
            .take(30)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

// ---- tests -------------------------------------------------------------------------------

#[test]
fn fixture_has_the_planned_cases() {
    assert!(cases("cn").len() >= 300 + 13);
    assert!(cases("vn").len() >= 15);
    assert!(
        cases("vn")
            .iter()
            .filter(|c| c["engineLunar"].is_array())
            .count()
            >= 6,
        "VN cases that need a leap remap or a 60-year shift"
    );
    assert!(fixture()["shiftEquivalenceChecks"].as_u64().unwrap() >= 100);
    assert!(fixture()["shiftDay30Checks"].as_u64().unwrap() >= 30);
    assert!(cases("lateZi").len() >= 5);
    let indices: std::collections::HashSet<_> = cases("cn")
        .iter()
        .map(|c| c["timeIndex"].as_u64().unwrap())
        .collect();
    assert_eq!(
        indices.len(),
        12,
        "time indices 0-11 (late Zi 12 never occurs)"
    );
    assert!(fixture()["leapEquivalenceChecks"].as_u64().unwrap() > 100);
}

#[test]
fn cn_charts_equal_iztro() {
    let svc = service();
    let cn = cases("cn");
    let mut mismatches = vec![];
    for c in &cn {
        let id = s(&c["id"]);
        let req = request(c, CalendarKind::Cn);
        let e = &c["expect"];
        // Our CN calendar must agree with iztro's for every fixture date.
        if req.birth.lunar != lunar(&e["lunar"]) {
            mismatches.push(format!(
                "{id}: lunar {:?} != iztro {}",
                req.birth.lunar, e["lunar"]
            ));
            continue;
        }
        match svc.chart(&req) {
            Ok(chart) => {
                assert_eq!(
                    chart.school,
                    "iztro-default;hour=local-standard;ty23=next-day"
                );
                assert_eq!(chart.lunar, req.birth.lunar);
                diff(
                    id,
                    &chart_lines(&chart),
                    &expected_chart_lines(e),
                    &mut mismatches,
                );
            }
            Err(err) => mismatches.push(format!("{id}: {err:#}")),
        }
    }
    assert_no_mismatches("CN charts", cn.len(), &mismatches);
}

#[test]
fn cn_flows_equal_iztro() {
    let svc = service();
    let cn = cases("cn");
    let mut mismatches = vec![];
    for c in &cn {
        let id = s(&c["id"]);
        let e = &c["expect"]["flow"];
        let day = date(&e["date"]);
        match svc.daily(&request(c, CalendarKind::Cn), day) {
            Ok(flow) => {
                assert_eq!(flow.date, day);
                assert_eq!(flow.day, day_can_chi(day), "{id}");
                if flow.lunar != lunar(&e["lunar"]) {
                    mismatches.push(format!(
                        "{id}: flow lunar {:?} != {}",
                        flow.lunar, e["lunar"]
                    ));
                }
                diff(
                    id,
                    &flow_lines(&flow),
                    &expected_flow_lines(e),
                    &mut mismatches,
                );
            }
            Err(err) => mismatches.push(format!("{id}: {err:#}")),
        }
    }
    assert_no_mismatches("CN flows", cn.len(), &mismatches);
}

#[test]
fn vn_charts_equal_iztro_by_lunar_input() {
    let svc = service();
    let vn = cases("vn");
    let mut mismatches = vec![];
    for c in &vn {
        let id = s(&c["id"]);
        let req = request(c, CalendarKind::Vn);
        assert_eq!(req.birth.lunar, lunar(&c["lunar"]), "{id}: VN lunar date");
        if c["engineLunar"].is_array() {
            let e = engine_lunar_date(req.birth.lunar).unwrap();
            assert_eq!(
                lunar(&c["engineLunar"]),
                LunarDate {
                    year: i32::try_from(e.year).unwrap(),
                    month: u8::try_from(e.month).unwrap(),
                    day: u8::try_from(e.day).unwrap(),
                    leap: e.leap,
                },
                "{id}: engine date"
            );
        }
        let e = &c["expect"];
        match svc.chart(&req) {
            Ok(chart) => {
                assert_eq!(
                    chart.school,
                    "iztro-default+vn-calendar;hour=local-standard;ty23=next-day"
                );
                assert_eq!(chart.lunar, lunar(&c["lunar"]));
                diff(
                    id,
                    &chart_lines(&chart),
                    &expected_chart_lines(e),
                    &mut mismatches,
                );
            }
            Err(err) => mismatches.push(format!("{id}: {err:#}")),
        }
        match svc.daily(&req, date(&e["flow"]["date"])) {
            Ok(flow) => diff(
                id,
                &flow_lines(&flow),
                &expected_flow_lines(&e["flow"]),
                &mut mismatches,
            ),
            Err(err) => mismatches.push(format!("{id}: {err:#}")),
        }
    }
    assert_no_mismatches("VN charts", vn.len(), &mismatches);
}

#[test]
fn vn_and_cn_charts_differ_for_1985_02_01() {
    let svc = service();
    let vn = cases("vn")
        .into_iter()
        .find(|c| c["id"] == "vn-1985-02-01-male")
        .unwrap();
    let vn_chart = svc.chart(&request(vn, CalendarKind::Vn)).unwrap();
    let cn_chart = svc.chart(&request(vn, CalendarKind::Cn)).unwrap();
    let ll = |y, m, d| LunarDate {
        year: y,
        month: m,
        day: d,
        leap: false,
    };
    assert_eq!(vn_chart.lunar, ll(1985, 1, 12));
    assert_eq!(cn_chart.lunar, ll(1984, 12, 12));
    assert_eq!(
        (vn_chart.year.stem, vn_chart.year.branch),
        (Stem::Yi, Branch::Chou)
    );
    assert_eq!(
        (cn_chart.year.stem, cn_chart.year.branch),
        (Stem::Jia, Branch::Zi)
    );
    assert_ne!(vn_chart.palaces, cn_chart.palaces);
}

